def letter_frequency(sentence):
    """
    This function takes a string as input and returns a dictionary containing the frequency of each letter in the string.

    Args:
        sentence (str): The input string.

    Returns:
        dict: A dictionary containing the frequency of each letter in the input string.

    Examples:
