def is_leap_year(year: int) -> bool:
    """
    Determines whether the given year is a leap year or not.

    Args:
        year: An integer representing the year to be checked.

    Returns:
        A boolean value indicating whether the year is a leap year or not.
    """

    # Leap years are exactly divisible by 4 except for century years (years ending with 00).
    # The century year is a leap year only if it is perfectly divisible by 400.
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False


